  for(int reward=0;reward<4;++reward){assert(g.state==State::Upgrade&&g.choosing_relic()&&g.choices.size()==3);std::set<int> ids;for(auto& c:g.choices)if(c.kind==UpgradeKind::Relic){int id=int(c.relic);assert(ids.insert(id).second&&relic_allowed(c.relic,CharacterClass(cls))&&(initial_relic_mask()&(1u<<id))&&!g.owns_relic(c.relic));}assert(!ids.empty());RelicId chosen=g.choices[0].relic;assert(g.choose_upgrade(0)&&g.owns_relic(chosen)&&g.metrics.relics_collected==reward+1);if(reward<3)blessing(g);}
  blessing(g);assert(g.state==State::Playing&&!g.choosing_relic()&&g.metrics.relics_collected==4);g.gems.push_back({g.player.pos,g.player.xp_next,0});g.update(.01f);assert(g.state==State::Upgrade&&!g.choosing_relic());resolve(g);
  // Owned relics, equipment snapshot and all existing stats survive repeated boundary restoration.
  g.config.duration=g.elapsed+.005f;g.update(.01f);resolve(g);assert(g.state==State::Victory); // Classic remains a complete single-run mode.
