 Game thunder=specimen(CharacterClass::Archer,RelicId::ThunderToken);for(int i=0;i<4;++i)thunder.enemies.push_back(foe(100+i,{100,float(i*20)},100));dead(thunder,12);int struck=0;for(auto& e:thunder.enemies)if(close_to(e.hp,80))++struck;assert(struck==3&&thunder.metrics.relic_procs[int(RelicId::ThunderToken)]==1&&close_to(thunder.metrics.other_damage,60));thunder.update(.01f);assert(thunder.kills==12&&thunder.metrics.relic_procs[int(RelicId::ThunderToken)]==1);
