 Game barbed=specimen(CharacterClass::Archer,RelicId::BarbedQuiver);barbed.enemies={foe(1)};projectile_hit(barbed,Skill::Arrow);assert(barbed.enemies[0].slow_remaining>.9f&&close_to(barbed.enemies[0].slow_factor,.6)&&barbed.metrics.relic_procs[int(RelicId::BarbedQuiver)]==1);projectile_hit(barbed,Skill::Arrow);assert(barbed.metrics.relic_procs[int(RelicId::BarbedQuiver)]==1);
 Game wind=specimen(CharacterClass::Archer,RelicId::WindFeather);wind.skills[int(Skill::Arrow)]=1;wind.enemies={foe(1,{400,0})};wind.update(.01f,{{1,0},true});assert(wind.metrics.relic_procs[int(RelicId::WindFeather)]==1&&!wind.projectiles.empty());wind.player.dash_cooldown=0;wind.update(.01f,{{1,0},true});assert(wind.metrics.relic_procs[int(RelicId::WindFeather)]==1);
