 Game ember=specimen(CharacterClass::Mage,RelicId::EmberCore);ember.enemies={foe(1)};projectile_hit(ember,Skill::Homing);assert(ember.enemies[0].burn_remaining>1.9f&&ember.metrics.relic_procs[int(RelicId::EmberCore)]==1);tick(ember,1.5f);assert(ember.metrics.skill_damage[int(Skill::Homing)]>5&&ember.metrics.skill_damage[int(Skill::Homing)]<30&&ember.metrics.relic_procs[int(RelicId::EmberCore)]==1);
 Game echo=specimen(CharacterClass::Mage,RelicId::EchoRune);echo.skills[int(Skill::Homing)]=1;echo.enemies={foe(1,{200,0})};tick(echo,.31f);assert(echo.metrics.relic_procs[int(RelicId::EchoRune)]==1);echo.skills.fill(0);echo.projectiles.clear();double before=echo.metrics.skill_damage[int(Skill::Homing)];tick(echo,.2f);assert(echo.metrics.skill_damage[int(Skill::Homing)]==before);tick(echo,.5f);assert(echo.metrics.skill_damage[int(Skill::Homing)]>before&&echo.metrics.skill_damage[int(Skill::Homing)]<before+20&&echo.metrics.relic_procs[int(RelicId::EchoRune)]==1);
